@staticmethod
    def _get_hidden_dim(shard_dim: int, ndim: int) -> int:
        """
        Return the index of the hidden dimension for an expert weight tensor.

        The hidden dimension is the one that is *not* sharded across tensor
        parallel ranks (i.e. the one that may be padded in the in-memory
        buffer relative to the checkpoint weight).

        :param shard_dim: the dimension along which the weight is sharded.
        :param ndim: the number of dimensions of the weight tensor.
        """
        if ndim == 1:
            return 0
        if ndim == 2:
            return 1 if shard_dim == 0 else 0
        if ndim == 3:
            if shard_dim == 1:
                return 2
            if shard_dim == 2:
                return 1
            raise ValueError("not a valid data dimension")
        raise ValueError("not a valid data dimension")

    @staticmethod
    def _narrow_expert_data_for_padding(
        expert_data: torch.Tensor,
        loaded_weight: torch.Tensor,
        hidden_dim: int,
    ) -> torch.Tensor:
        """
        Narrow ``expert_data`` along ``hidden_dim`` so that the real
        checkpoint weight can be copied into the (possibly padded) in-memory
        buffer without a shape mismatch.

        Only the ``hidden_dim`` axis is narrowed; all other axes keep their
        original sizes. The returned tensor is a view that shares storage with
        ``expert_data``, so ``copy_`` into it writes back to the buffer.

        ``expert_data`` is returned unchanged when it is not larger than
        ``loaded_weight`` along ``hidden_dim``, when ``loaded_weight`` is a
        scalar (0-dim) tensor, or when ``hidden_dim`` is negative.
        """
        if loaded_weight.ndim == 0 or hidden_dim < 0:
            return expert_data
        if expert_data.shape[hidden_dim] > loaded_weight.shape[hidden_dim]:
            return expert_data.narrow(
                hidden_dim, 0, loaded_weight.shape[hidden_dim]
            )
        return expert_data

